// Builds audio-data.js, MAP.md, ASSETS.md and credits.html for Final Approach from samples already cut and normalised for earlier games
// (../<game>/audio-data.js, see ../ASSETS.md for the source files and licences). Run: node bundle_fa.js
const fs = require('fs'), path = require('path');
const load = g => new Function(fs.readFileSync(path.join(__dirname, '..', g, 'audio-data.js'), 'utf8').replace(/^const /m, 'var ') + ';return GA_DATA')();
const D = { nebula: load('nebula'), crown: load('crown'), rampart: load('rampart'), shipwreck: load('shipwreck') };
const PICK = [ // [name, game, sample, use]
  ['click', 'nebula', 'click', 'buttons'], ['error', 'nebula', 'error', 'illegal move'], ['dieland', 'crown', 'clack', 'a die lands in a slot'], ['roll', 'crown', 'shake', 'dice are rolled behind the screens / a reroll'],
  ['switch', 'nebula', 'token', 'gear, flaps or brake switch flips'], ['beep', 'nebula', 'lock', 'radio call clears a plane'], ['engine', 'nebula', 'engine', 'engine markers move'], ['whoosh', 'crown', 'whoosh', 'axis moves'],
  ['coffee', 'rampart', 'coins', 'a coffee is used'], ['round', 'nebula', 'turn', 'round ends, plane advances'], ['win', 'nebula', 'win', 'safe landing'], ['lose', 'nebula', 'lose', 'flight lost'],
  ['alarm', 'nebula', 'stress', 'warning: axis, fuel or collision close'], ['boom', 'nebula', 'boom', 'crash'], ['hum', 'nebula', 'engine_loop', 'cabin engine hum, loop under the music']];
const sfx = {}; for (const [n, g, s] of PICK) { if (!D[g].sfx[s]) throw new Error('missing ' + g + '/' + s); sfx[n] = D[g].sfx[s]; }
const music = {}; for (const k of ['tavern', 'main', 'fight', 'victory', 'defeat']) for (const v of 'ab') music[k + '-' + v] = 'url:music/' + k + '-' + v + '.mp3'; // Treblo files in games/final-approach/music/
fs.writeFileSync(path.join(__dirname, 'audio-data.js'), '/* audio-data.js for Final Approach - generated by audio/final-approach/bundle_fa.js from samples already bundled for other games. Licences: see ASSETS.md and audio/ASSETS.md */\nconst GA_DATA=' + JSON.stringify({ sfx, music }) + ';\n');
const kb = s => Math.round(s.length * .75 / 1024);
const rows = PICK.map(([n, g, s, u]) => '| `' + n + '` | ' + g + '/' + s + ' | ' + kb(sfx[n]) + ' KB | ' + u + ' |');
fs.writeFileSync(path.join(__dirname, 'MAP.md'), '# Final Approach: sound map\n\nLoad order: `gameaudio.js`, `audio-data.js`, then the game. `GA.init({sfx:GA_DATA.sfx, music:GA_DATA.music, key:...})`. Events are mapped in `SND_MAP` (game/src/ui6.js). Nobody has auditioned these by ear: tune per-sound `vol` there.\n\n| sample | reused from | size | use |\n|---|---|---|---|\n' + rows.join('\n') + '\n| `music.<slot>-a/b` | Treblo files in games/final-approach/music/, fetched when first wanted | tavern = menu, main = flight, fight = last round or boss airport, victory / defeat = end cues |\n');
const src = `# Final Approach: audio assets

Nothing here is new: every sample is reused from the bundles already cut, normalised and licence-checked for earlier games (mono MP3 64 kbps; music stereo 96 kbps). The per-file source, author, licence URL and date checked are in \`../ASSETS.md\` under the "used as" names below. Licence snapshots (Kenney pack pages and licence files, the rubberduck pack page, the Seaside Village page): \`licence-snapshots/\`. All CC0 1.0 (https://creativecommons.org/publicdomain/zero/1.0/). No attribution is required but credits.html names the authors anyway.

| sample here | "used as" in ../ASSETS.md | author / pack | licence |
|---|---|---|---|
${PICK.map(([n, g, s]) => '| `' + n + '` | ' + g + '/' + s + ' | ' + ({ nebula: 'Kenney (Interface Sounds, Digital Audio, Sci-fi Sounds, Music Jingles, UI Audio)', crown: 'Kenney Casino Audio; rubberduck "100 CC0 SFX #2"', rampart: 'Kenney RPG Audio' }[g]) + ' | CC0 1.0 |').join('\n')}
| \`music.<slot>-a/b\` | Treblo (own prompts, 2026-10-08) | Ten instrumentals generated on treblo.com by the project owner; Treblo Terms of Service section 8: the user owns the Outputs. Cut by audio/tools/music_treblo.py (-18 LUFS, 96 kbps). Treblo gives no warranty that a track can be copyrighted. | Treblo terms |

Rebuild: \`node bundle_fa.js\`.
`;
fs.writeFileSync(path.join(__dirname, 'ASSETS.md'), src);
fs.writeFileSync(path.join(__dirname, 'credits.html'), `<!-- Credits snippet for Final Approach. -->
<section class="credits-audio">
<h3>Audio</h3>
<p>With thanks to these public-domain (CC0) creators:</p>
<ul>
<li>Music: ten instrumental tracks (Cockpit Drift, Gate 47 6 A.M., Final Approach, Final Descent Perfect Landing, Sheepish Shuffle) generated with Treblo (treblo.com) by the game owner, who owns the outputs under the Treblo Terms of Service.</li>
<li>Sound effects: Casino Audio, Digital Audio, Interface Sounds, Music Jingles, RPG Audio, Sci-fi Sounds, UI Audio by <a href="https://kenney.nl">Kenney</a> (CC0)</li>
<li>Sound effects: &ldquo;100 CC0 SFX #2&rdquo; by rubberduck (<a href="https://opengameart.org/content/100-cc0-sfx-2">OpenGameArt</a>, CC0)</li>
</ul>
<p><small>All sounds were trimmed, loudness-normalised and converted to MP3.</small></p>
</section>
`);
console.log('ok', Object.keys(sfx).length, 'sfx', Object.keys(music).length, 'music files');
